def study(id,title,population,week,total,analysis,measure,unit,rows,source,note,**kw):
 return dict(id=id,title=title,population=population,weeks=week,randomised=total,analysis=analysis,measure=measure,unit=unit,rows=[dict(label=a,value=b) for a,b in rows],source=source,note=note,**kw)
