def med(id,name,ingredient,path,status,route,targets,summary,answer,safety,refs,trial=(),**kw):
 return dict(id=id,name=name,ingredient=ingredient,path=path,status=status,route=route,targets=targets,summary=summary,answer=answer,safety=safety,sources=refs,studies=list(trial),**kw)
